//! Oracle reader shared by the text range-selector tests (G38b / L06-G).
//!
//! `fixtures/text-glyph-selector/oracle.txt` is generated by `tools/gen.js` from
//! the VERBATIM `src/js/text-selector.js` (and `taUnitCount` of
//! `src/js/motion.js`) at fbe4b8a3 in a Node vm, with the engine's own `Math`
//! (Node's V8). A row that never reaches `Math.sin` / `Math.cos` must be equal
//! bit for bit. A row that does (a Wiggly weight, the SMOOTH shape, `hashRand`,
//! `smoothNoise1D`) is held within [`V8_TOLERANCE`]: the kernel runs Rust
//! `f64::sin` / `f64::cos`, which equal JavaScriptCore on the macOS desktop but
//! can differ from V8 (and from another host's libm) by an ulp of the sine,
//! which the hash's 43758.5453 factor turns into about 5e-12 (measured worst
//! V8-versus-fdlibm deviation: 2.7e-12).
//!
//! Rows (` | ` separates the inputs from the answers, numbers are JS
//! `String(n)` with `-0` kept, `-` is undefined / null):
//! * `SEL16` = `type(r|w) start end offset units(p|i) basedOn(c|w|l) shape amount
//!   easeHigh easeLow smooth wiggleMin wiggleMax wigglesPerSec correlation seed`.
//!   A `-` in `start`, `offset`, `shape`, `easeHigh`, `easeLow` or `seed` (the JS
//!   `||` fields) reads as `0.0`: `undefined || d` and `0 || d` are the same.
//! * `W SEL16 ind total time | w` (`weightAt`), `RR SEL16 total | s e`
//!   (`resolveRange`), `WS SEL16 total time | n w,..` (`weights`, `~` is empty).
//! * `H seed i | v`, `N seed t | v`, `B x1 y1 x2 y2 x | y`.
//! * `U basedOn c:w:l | idx` (`unitIndexOf`), `C basedOn c:w:l,.. | n`
//!   (`taUnitCount`, `~` is no strokes).

use crate::evaluation::object_text_layout_kernels::text_glyph_selector::{
    BasedOn, Selector, SelectorType, UnitIndices, Units, SHAPE_SMOOTH,
};

pub(crate) const ORACLE: &str = include_str!("fixtures/text-glyph-selector/oracle.txt");

/// Allowed `|kernel - baseline|` on rows that call `sin` / `cos`.
pub(crate) const V8_TOLERANCE: f64 = 1e-9;

/// A mutated rule must be at least this far from the baseline answer to count as caught.
pub(crate) const MUTANT_GAP: f64 = 1e-6;

pub(crate) fn num(token: &str) -> f64 {
    token
        .parse::<f64>()
        .unwrap_or_else(|_| panic!("bad number {token:?}"))
}

fn opt(token: &str) -> Option<f64> {
    (token != "-").then(|| num(token))
}

fn or_zero(token: &str) -> f64 {
    opt(token).unwrap_or(0.0)
}

pub(crate) fn selector(t: &[&str]) -> Selector {
    assert_eq!(t.len(), 16, "SEL16 {t:?}");
    Selector {
        selector_type: if t[0] == "w" {
            SelectorType::Wiggly
        } else {
            SelectorType::Range
        },
        start: or_zero(t[1]),
        end: opt(t[2]),
        offset: or_zero(t[3]),
        units: if t[4] == "i" {
            Units::Index
        } else {
            Units::Percent
        },
        based_on: match t[5] {
            "w" => BasedOn::Words,
            "l" => BasedOn::Lines,
            _ => BasedOn::Chars,
        },
        shape: or_zero(t[6]),
        amount: opt(t[7]),
        ease_high: or_zero(t[8]),
        ease_low: or_zero(t[9]),
        smooth: opt(t[10]),
        wiggle_min: opt(t[11]),
        wiggle_max: opt(t[12]),
        wiggles_per_sec: opt(t[13]),
        correlation: opt(t[14]),
        seed: or_zero(t[15]),
    }
}

pub(crate) fn based_on(token: &str) -> BasedOn {
    BasedOn::from_baseline(token)
}

fn indices(token: &str) -> UnitIndices {
    let p: Vec<&str> = token.split(':').collect();
    UnitIndices {
        char_index: opt(p[0]),
        word_index: opt(p[1]),
        line_index: opt(p[2]),
    }
}

#[derive(Debug)]
pub(crate) enum Row {
    Weight {
        sel: Selector,
        ind: f64,
        total: f64,
        time: f64,
        want: f64,
    },
    Range {
        sel: Selector,
        total: f64,
        s: f64,
        e: f64,
    },
    Weights {
        sel: Selector,
        total: f64,
        time: f64,
        want: Vec<f64>,
    },
    Hash {
        seed: f64,
        i: f64,
        want: f64,
    },
    Noise {
        seed: f64,
        t: f64,
        want: f64,
    },
    Bezier {
        p: [f64; 4],
        x: f64,
        y: f64,
    },
    UnitIndex {
        based_on: BasedOn,
        sd: UnitIndices,
        want: Option<f64>,
    },
    UnitCount {
        based_on: BasedOn,
        glyphs: Vec<UnitIndices>,
        want: f64,
    },
}

fn list(token: &str) -> Vec<f64> {
    if token == "~" {
        Vec::new()
    } else {
        token.split(',').map(num).collect()
    }
}

pub(crate) fn rows() -> Vec<Row> {
    let mut out = Vec::new();
    for line in ORACLE
        .lines()
        .filter(|l| !l.is_empty() && !l.starts_with('#'))
    {
        let parts: Vec<&str> = line.split(" | ").collect();
        let t: Vec<&str> = parts[0].split(' ').collect();
        let r: Vec<&str> = parts.get(1).map_or(Vec::new(), |p| p.split(' ').collect());
        out.push(match t[0] {
            "W" => Row::Weight {
                sel: selector(&t[1..17]),
                ind: num(t[17]),
                total: num(t[18]),
                time: num(t[19]),
                want: num(r[0]),
            },
            "RR" => Row::Range {
                sel: selector(&t[1..17]),
                total: num(t[17]),
                s: num(r[0]),
                e: num(r[1]),
            },
            "WS" => Row::Weights {
                sel: selector(&t[1..17]),
                total: num(t[17]),
                time: num(t[18]),
                want: list(r[1]),
            },
            "H" => Row::Hash {
                seed: num(t[1]),
                i: num(t[2]),
                want: num(r[0]),
            },
            "N" => Row::Noise {
                seed: num(t[1]),
                t: num(t[2]),
                want: num(r[0]),
            },
            "B" => Row::Bezier {
                p: [num(t[1]), num(t[2]), num(t[3]), num(t[4])],
                x: num(t[5]),
                y: num(r[0]),
            },
            "U" => Row::UnitIndex {
                based_on: based_on(t[1]),
                sd: indices(t[2]),
                want: opt(r[0]),
            },
            "C" => Row::UnitCount {
                based_on: based_on(t[1]),
                glyphs: if t[2] == "~" {
                    Vec::new()
                } else {
                    t[2].split(',').map(indices).collect()
                },
                want: num(r[0]),
            },
            other => panic!("unknown oracle row {other}"),
        });
    }
    out
}

/// Bit equality (`-0` and `0` differ), the contract of a row that never reaches `sin` / `cos`.
pub(crate) fn same(a: f64, b: f64) -> bool {
    a.to_bits() == b.to_bits()
}

/// Whether a selector's weight calls `Math.sin` (Wiggly hash) or `Math.cos` (SMOOTH shape).
pub(crate) fn uses_trig(sel: &Selector) -> bool {
    sel.selector_type == SelectorType::Wiggly || sel.shape == SHAPE_SMOOTH
}

/// The row contract: bit for bit, or within [`V8_TOLERANCE`] when the row reaches `sin` / `cos`.
pub(crate) fn matches_baseline(trig: bool, got: f64, want: f64) -> bool {
    if trig {
        (got - want).abs() <= V8_TOLERANCE
    } else {
        same(got, want)
    }
}
